package admin_shell;

// Interactive administrative shell service. The client and server exchange a
// bidirectional stream of messages: the client sends input read from the
// operator's terminal, and the server streams back the shell's output.
service AdminShell {
  rpc Shell(stream ClientMessage) returns (stream ServerMessage);
}

// A message sent from the client (operator) to the server.
message ClientMessage {
  oneof message {
    // Raw input bytes to feed to the shell.
    bytes input = 1;
  }
}

// A message sent from the server back to the client.
message ServerMessage {
  oneof message {
    // Raw output bytes produced by the shell.
    bytes output = 1;
    // The shell has exited with the given status code.
    int32 exit_code = 2;
  }
}
